(()=>{'use strict';const trigger=document.querySelector('#deskSearch'),header=document.querySelector('main>header');if(!trigger||!header)return;
const date=document.querySelector('#deskDate'),account=header.querySelector('.header-tools');if(date&&account){const keepDate=()=>{if(account.firstElementChild!==date)account.prepend(date)};keepDate();new MutationObserver(keepDate).observe(account,{childList:true})}
const box=document.createElement('div');box.id='headerSearchBox';box.className='header-search-box';box.innerHTML='<span aria-hidden="true"><svg viewBox="0 0 24 24" width="20" height="20" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round"><circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 4.5 4.5"/></svg></span><input type="search" id="headerTaskSearch" placeholder="جست‌وجوی کار، مسئول یا همکار…" aria-label="جست‌وجوی کارها" autocomplete="off"><button type="button" aria-label="بستن پیشنهادها">×</button>';header.append(box);
const panel=document.createElement('div');panel.className='header-search-popover';panel.id='headerSearchPanel';panel.setAttribute('popover','manual');panel.hidden=true;const results=document.createElement('div');results.className='search-suggestions';results.id='headerSearchSuggestions';const resultStatus=document.createElement('p');resultStatus.className='search-result-status';resultStatus.setAttribute('role','status');panel.append(resultStatus,results);document.body.append(panel);
const input=box.querySelector('input'),closeButton=box.querySelector('button');input.setAttribute('aria-controls',panel.id);input.setAttribute('aria-expanded','false');let timer,opened=false;
function position(){const r=box.getBoundingClientRect(),width=Math.min(innerWidth-24,Math.max(r.width,360));panel.style.width=width+'px';panel.style.left=Math.max(12,Math.min(innerWidth-width-12,r.right-width))+'px';panel.style.top=r.bottom+8+'px';panel.style.maxHeight=Math.max(100,Math.min(340,innerHeight-r.bottom-24))+'px'}
function open(){if(opened)return;opened=true;header.classList.add('header-search-open');document.body.classList.add('search-suggest-open');panel.hidden=false;if(typeof panel.showPopover==='function')panel.showPopover();position();suggest();input.setAttribute('aria-expanded','true');input.focus()}
function close(){if(!opened)return;if(timer){clearTimeout(timer);timer=null;apply()}opened=false;if(typeof panel.hidePopover==='function'&&panel.matches(':popover-open'))panel.hidePopover();panel.hidden=true;header.classList.remove('header-search-open');document.body.classList.remove('search-suggest-open');input.setAttribute('aria-expanded','false')}
function suggest(){results.replaceChildren();if(!input.value.trim()){resultStatus.textContent='برای جست‌وجوی کار، مسئول یا همکار، عبارت موردنظر را بنویسید.';return}const host=document.querySelector('#sharedApp,#workspace');if(!host)return;const seen=new Set(),items=[];for(const b of host.querySelectorAll('[data-task],[data-shared-card],[data-personal-edit]')){const id=b.dataset.task||b.dataset.sharedCard||b.dataset.personalEdit;if(seen.has(id))continue;seen.add(id);const row=b.closest('.personal-task-row,tr,.desk-task-card');let meta={};try{meta=JSON.parse(row?.dataset.taskSort||'{}')}catch{}const task=typeof tasks!=='undefined'?tasks.find(t=>t.id===id):null;const term=input.value.trim(),candidate={...task,title:meta.title||task?.title||b.textContent.trim(),description:[task?.description,row?.textContent].filter(Boolean).join(' ')};if(term&&!(window.SamandisTaskMatches?SamandisTaskMatches(candidate,term):candidate.description.toLocaleLowerCase().includes(term.toLocaleLowerCase())))continue;items.push({id,title:meta.title||task?.title||b.textContent.trim(),owner:meta.owner||(task?(document.body.classList.contains('shared-app')&&typeof person==='function'?person(task.owner_id):typeof people!=='undefined'?people[task.owner]||'':''):''),node:b})}const query=input.value.trim();resultStatus.textContent=query?(items.length?items.length.toLocaleString('fa-IR')+' کار مرتبط در این بخش':'کاری با این عبارت پیدا نشد.'): 'برای شروع تایپ کنید؛ کارهای این بخش';for(const item of items.slice(0,5)){const b=document.createElement('button');b.type='button';b.className='search-suggestion';const glyph=document.createElement('span');glyph.className='search-suggestion-icon';glyph.textContent='↗';glyph.setAttribute('aria-hidden','true');const text=document.createElement('span'),title=document.createElement('strong'),sub=document.createElement('small');title.textContent=item.title;sub.textContent=item.owner||'مشاهدهٔ اطلاعات کار';text.append(title,sub);b.append(glyph,text);b.onclick=()=>{close();item.node.click()};b.onkeydown=e=>{const buttons=[...results.querySelectorAll('button')],i=buttons.indexOf(b);if(e.key==='ArrowDown'){e.preventDefault();buttons[(i+1)%buttons.length]?.focus()}if(e.key==='ArrowUp'){e.preventDefault();if(i===0)input.focus();else buttons[i-1]?.focus()}if(e.key==='Escape'){e.preventDefault();close()}};results.append(b)}if(items.length>5){const more=document.createElement('small');more.className='search-more-hint';more.textContent='برای پیشنهادهای دقیق‌تر، عبارت بیشتری بنویسید.';results.append(more)}}function apply(){suggest()}
trigger.onclick=()=>{open();input.focus()};input.addEventListener('focus',open);input.addEventListener('click',open);closeButton.onclick=()=>{close();input.blur()};input.oninput=()=>{if(!opened)open();clearTimeout(timer);timer=setTimeout(()=>{timer=null;apply()},140)};input.onkeydown=e=>{if(e.key==='ArrowDown'){e.preventDefault();results.querySelector('button')?.focus()}if(e.key==='Escape'){e.preventDefault();close()}if(e.key==='Enter'){e.preventDefault();clearTimeout(timer);timer=null;apply()}};
document.addEventListener('pointerdown',e=>{if(opened&&!box.contains(e.target)&&!panel.contains(e.target))close()});document.addEventListener('keydown',e=>{if(e.key==='/'&&!e.ctrlKey&&!e.metaKey&&!e.altKey&&!document.querySelector('dialog[open]')&&!/INPUT|TEXTAREA|SELECT/.test(e.target.tagName)&&!e.target.isContentEditable){e.preventDefault();open();input.focus()}if(e.key==='Escape'&&opened)close()},true);window.addEventListener('resize',()=>{if(opened)position()});document.addEventListener('scroll',e=>{if(opened&&!panel.contains(e.target))close()},true);
})();
